mapper.delete:
DELETE FROM RSK_OCCUPY_INFO T
--删除平台日(跑批日)之前的实占数据（剔除实占记录对应预占数据生效的那部分实占数据）
WHERE T.EVENT_DATE < #{sysDate}
AND EVENT_ID NOT IN (
    SELECT t1.EVENT_ID FROM RSK_OCCUPY_INFO t1
    INNER JOIN RSK_PRE_OCCUPY_INFO t2 ON t1.OCCUPY_CODE = t2.EVENT_ID
    WHERE t2.OCCUPY_DATE >= #{sysDate}
    AND t2.OCP_STATUS = '0'
)
